          padding: 24px;
          max-width: 900px;
          margin: 0 auto;
        }
        h1 {
          font-weight: 600;
          margin-bottom: 24px;
          font-size: 1.8rem;
        }
        .cards-container {
          display: flex;
          gap: 24px;
          margin-bottom: 32px;
          flex-wrap: wrap;
        }
        .card {
          border: 1.5px solid #999;
          border-radius: 8px;
          padding: 16px 20px;
          flex: 1 1 280px;
          min-width: 280px;
          box-shadow: 1px 1px 4px #ddd;
          display: flex;
          flex-direction: column;
          justify-content: space-between;
        }
        .card h2 {
          font-weight: 600;
          font-size: 1.2rem;
          margin: 0 0 8px 0;
        }
        .card p {
          margin: 0 0 16px 0;
          font-weight: 500;
          font-size: 1rem;
        }
