          align-self: flex-start;
          padding: 8px 16px;
          font-size: 1rem;
          border: 2px solid #444;
          border-radius: 6px;
          background: white;
          cursor: pointer;
          transition: background-color 0.2s ease, color 0.2s ease;
          font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
        }
        button:hover {
          background-color: #444;
          color: white;
        }
        .message {
          margin-top: 12px;
          font-weight: 600;
          color: #b22222;
        }
        .spending-chart {
          border: 1.5px solid #999;
          border-radius: 8px;
          padding: 12px 16px;
          font-weight: 600;
          font-size: 1.1rem;
          box-shadow: 1px 1px 4px #ddd;
        }
        .chart-box {
          margin-top: 12px;
          border: 1.5px solid #999;
          border-radius: 6px;
          height: 100px;
          position: relative;
          background: #fafafa;
        }
        svg {
          width: 100%;
          height: 100%;
          display: block;
        }
        .statement-page {
          max-width: 700px;
          margin: 0 auto;
