                <p>Balance $3,200</p>
                <button onClick={freezeVisaCard} disabled={visaFrozen} aria-live="polite">
                  Freeze card
                </button>
                {visaFrozen && (
                  <p className="message" role="alert">Card frozen</p>
                )}
              </article>

              <article className="card" aria-label="Mastercard card ending 7710">
                <h2>Mastercard 7710</h2>
                <p>Balance $940</p>
                <button onClick={goToStatement} aria-haspopup="dialog">
                  View statement
                </button>
              </article>
            </section>

            <section className="spending-chart" aria-label="Spending chart">
              Spending
              <div className="chart-box">
                <svg viewBox="0 0 100 40" aria-hidden="true" focusable="false">
                  <polyline
                    fill="none"
                    stroke="#444"
                    strokeWidth="2"
                    points="0,10 20,15 40,20 60,20 80,30 100,25"
                  />
                </svg>
              </div>
            </section>
          </>
        )}

        {view === "statement" && (
          <section className="statement-page" role="dialog" aria-modal="true" aria-labelledby="statement-title">
            <h2 id="statement-title">Mastercard 7710 Statement</h2>
            <p>This is your statement page for Mastercard 7710.</p>
            <p>Here you would see your transactions and details.</p>
            <button className="back-button" onClick={goBack} aria-label="Back to cards overview">
              Back
            </button>
          </section>
        )}

        {view === "accounts" && (
          <section>
            <h1>Accounts</h1>
            <p>This is a placeholder for the Accounts page.</p>
          </section>
        )}

        {view === "help" && (
          <section>
            <h1>Help</h1>
            <p>This is a placeholder for the Help page.</p>
          </section>
        )}
      </main>
    </>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<App />);

